pub fn rebalance(counts: &mut Vec<i32>) {
    let n = counts.len();
    let first = &mut counts[0];
    let last = &mut counts[n - 1];
    let mid = (*first + *last) / 2;
    *first = mid;
    *last = mid;
}

pub fn run() -> Vec<i32> {
    let mut c = vec![10, 5, 4];
    rebalance(&mut c);
    c
}

