exercises.solution:
pub fn rebalance(counts: &mut Vec<i32>) {
    let n = counts.len();
    let (head, tail) = counts.split_at_mut(n - 1);
    let first = &mut head[0];
    let last = &mut tail[0];
    let mid = (*first + *last) / 2;
    *first = mid;
    *last = mid;
}

pub fn run() -> Vec<i32> {
    let mut c = vec![10, 5, 4];
    rebalance(&mut c);
    c
}
